import{_ as s,C as t,o as r,c as o,E as a,a2 as l}from"./chunks/framework.VWKgVqrc.js";const y=JSON.parse('{"title":"Why lower latency can leave timely task delivery unchanged","description":"","frontmatter":{"title":"Why lower latency can leave timely task delivery unchanged","date":"2026-11-04","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"完整任务的延迟改善何时不增加按期交付，成功样本筛选与计时窗口怎样影响读数？","research_question_en":"When does lower complete-task latency leave timely delivery unchanged, and how do success selection and timing windows affect the reading?","summary":"Four tasks falling from 12 to 11 seconds still miss a fixed deadline; changing success flags alone can also improve successful-task median latency. Neither mechanism is a measured serving speedup.","sources":"Pinned task-metric code, same-date internal experiments and the MAServeBench v2 paper","pageClass":"runtime-v6-article","item_id":"SIG-20261104-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-04-sig-20261104-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-11-04-sig-20261104-006.md","filePath":"en/engineering/2026-11-04-sig-20261104-006.md","lastUpdated":null}'),d={name:"en/engineering/2026-11-04-sig-20261104-006.md"};function c(h,e,u,m,p,g){const n=t("ArticleCover"),i=t("ArticleTableScroll");return r(),o("div",null,[a(n,{image:"/assets/covers/daily-2026-11-04-sig-20261104-006-cover.png",kicker:"Research",title:"Why lower latency can leave timely task delivery unchanged",summary:"Four tasks falling from 12 to 11 seconds still miss a fixed deadline; changing success flags alone can also improve successful-task median latency. Neither mechanism is a measured serving speedup.",version:"2026-11-04",languageHref:"/zh/engineering/2026-11-04-sig-20261104-006",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=l('<h1 id="why-lower-latency-can-leave-timely-task-delivery-unchanged" tabindex="-1">Why lower latency can leave timely task delivery unchanged <a class="header-anchor" href="#why-lower-latency-can-leave-timely-task-delivery-unchanged" aria-label="Permalink to &quot;Why lower latency can leave timely task delivery unchanged&quot;">​</a></h1><p>Every task in a four-task cohort falls from 12 to 11 seconds, yet timely completions stay at zero. With a 10-second deadline, that is entirely possible. Another change is easier to misread: leave raw latencies untouched, mark two slow tasks as failures, and successful-task median latency falls from 9 to 5.5 seconds.</p><p>Engineers evaluating multi-agent serving need different explanations for those two improvements. One fails to cross a delivery threshold; the other changes the statistical population. Internal module controls separate the mechanisms here. They help readers check deadlines, counts, percentile cohorts and measurement windows; they do not identify a serving optimization already shown to be faster.</p><h2 id="four-faster-tasks-can-still-yield-no-more-timely-deliveries" tabindex="-1">Four faster tasks can still yield no more timely deliveries <a class="header-anchor" href="#four-faster-tasks-can-still-yield-no-more-timely-deliveries" aria-label="Permalink to &quot;Four faster tasks can still yield no more timely deliveries&quot;">​</a></h2><p>The same-date research executed the pinned <a href="https://raw.githubusercontent.com/ShengxuanQiu/MAServeBench/22483ab5df5eff562061953d564aac47a9423c2f/mas_workflow/app/semantic/metrics.py" target="_blank" rel="noreferrer">MAServeBench task-metric module</a> with four synthetic tasks, a 20-second measurement duration and a 10-second deadline. Every task is marked successful; paired controls change only raw wall-clock latency. The seconds are stipulated array values, not completion times measured on a server.</p><table tabindex="0"><thead><tr><th>Internal synthetic control</th><th style="text-align:right;">Latency per task</th><th style="text-align:right;">Attempted</th><th style="text-align:right;">Successful</th><th style="text-align:right;">Timely</th><th style="text-align:right;">Task goodput</th></tr></thead><tbody><tr><td>Baseline input</td><td style="text-align:right;">12 seconds</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td><td style="text-align:right;">0 tasks/s</td></tr><tr><td>Faster but still late</td><td style="text-align:right;">11 seconds</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">0</td><td style="text-align:right;">0 tasks/s</td></tr><tr><td>At the deadline boundary</td><td style="text-align:right;">10 seconds</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">0.2 tasks/s</td></tr></tbody></table><p>Source: same-date internal baseline, faster-but-late and deadline-boundary module controls; all inputs are synthetic.</p><p>The code counts a successful task as timely when latency is no greater than the deadline, then divides timely completions by the caller-supplied duration. The first two rows have different latencies but identical threshold counts. At 10 seconds, the inclusive predicate counts all four tasks, giving 4/20 = 0.2 tasks/s.</p><p>This does not make a reduction from 12 to 11 seconds worthless. It means the reduction does not automatically fulfill a 10-second delivery commitment. Continuous latency statistics alone cannot answer a deadline-delivery question. Conversely, a threshold count does not describe how severely late tasks miss their deadline; both observables have a role.</p><h2 id="a-lower-median-can-reflect-the-loss-of-slow-successes" tabindex="-1">A lower median can reflect the loss of slow successes <a class="header-anchor" href="#a-lower-median-can-reflect-the-loss-of-slow-successes" aria-label="Permalink to &quot;A lower median can reflect the loss of slow successes&quot;">​</a></h2><p>The second pair retains raw latencies of 5, 6, 12 and 20 seconds. All four tasks succeed in the first input. Only the 12- and 20-second tasks are marked failed in the second. No task executes faster.</p><table tabindex="0"><thead><tr><th>Internal synthetic control</th><th style="text-align:right;">Successful</th><th style="text-align:right;">Successful-task median</th><th style="text-align:right;">Attempted</th><th style="text-align:right;">Timely</th><th style="text-align:right;">Attainment</th></tr></thead><tbody><tr><td>All four successful</td><td style="text-align:right;">4</td><td style="text-align:right;">9 seconds</td><td style="text-align:right;">4</td><td style="text-align:right;">2</td><td style="text-align:right;">0.5</td></tr><tr><td>Two slow tasks marked failed</td><td style="text-align:right;">2</td><td style="text-align:right;">5.5 seconds</td><td style="text-align:right;">4</td><td style="text-align:right;">2</td><td style="text-align:right;">0.5</td></tr></tbody></table><p>Source: same-date internal before/after success-selection controls. This module calculates percentiles from valid successful-task latencies and attainment over all recorded attempts.</p><p>The improved median with unchanged attainment now comes from selection, rather than a deadline plateau. These mechanisms cannot be combined into a speedup. Successful-task percentiles remain useful when labeled as such and accompanied by attempted, successful and timely counts.</p><p>A further internal control supplies a 5-second success, a 6-second failure, a task marked successful with missing latency, and a 12-second success. The module returns four attempts, three successes, one timely task and attainment 0.25. Failures and missing latency remain in the attempted denominator. That denominator nevertheless covers recorded attempts only; the module cannot discover attempts that callers never recorded.</p><h2 id="the-clock-and-run-validity-remain-separate-conditions" tabindex="-1">The clock and run validity remain separate conditions <a class="header-anchor" href="#the-clock-and-run-validity-remain-separate-conditions" aria-label="Permalink to &quot;The clock and run validity remain separate conditions&quot;">​</a></h2><p>Tasks can include external waits. A control supplies both 12 seconds of raw wall-clock latency and 1 second of net latency. The pinned module prefers the raw time and still reports zero timely tasks. Removing a wait from a local timing statistic does not shorten arrival-to-completion time experienced by a recipient.</p><p>Positive metrics also cannot establish run validity. An internal control marks a run invalid while supplying one successful 5-second task; the module still emits 0.05 tasks/s and attainment 1. Such numbers may be diagnostic without qualifying the run for a valid performance comparison. A separate capacity-helper control supplies three synthetic load cells: load 1 is valid and meets the target; load 2 meets it numerically but is invalid; load 3 is valid but misses it. At target 0.9, the helper returns maximum tested qualifying load 1, already filtering the invalid cell. This is not an executed load sweep or evidence of an implementation defect.</p><p>The caller also owns the observation window. The <a href="https://arxiv.org/html/2610.40293v2" target="_blank" rel="noreferrer">v2 paper&#39;s complete-task counting protocol</a> distinguishes arrival-window goodput from a drain-inclusive timely-task rate. The first uses the fixed arrival window; the second and token throughput use the larger of that window and cohort completion duration. A module receiving one duration parameter cannot reconstruct the required arrival cohort and drain window by itself.</p><h2 id="paper-performance-findings-occupy-a-different-evidence-layer" tabindex="-1">Paper performance findings occupy a different evidence layer <a class="header-anchor" href="#paper-performance-findings-occupy-a-different-evidence-layer" aria-label="Permalink to &quot;Paper performance findings occupy a different evidence layer&quot;">​</a></h2><p>The module mechanisms relate to the question raised by <a href="https://arxiv.org/html/2610.40293v2" target="_blank" rel="noreferrer">Section 6.6 and the high-load table in the v2 paper</a>, but do not reproduce its hardware experiment. At the highest load, the authors report that raising the DAG execution&#39;s KV budget from 16 to 40 GiB gives paired-block median ratios of 1.0774 for token throughput and 0.8451 for root-task P95 latency. Median deadline goodput remains near zero, and one paired block loses one timely root.</p><p>Those author-reported findings cannot be inserted into the four-task table or compounded with the request-limit sensitivity experiment. They have distinct loads, hardware/model conditions, paired units and deadlines. The paper also retains low-load, loose- or strict-deadline ties and binding-dependent results. Our interpretation supports possible divergence among metrics, rather than a universal ranking of release policies or cache configurations.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>This article uses completed same-date research. Nine internal controls executed and passed; their <a href="/joinwell52/assets/evidence/2026-11-04-sig-20261104-006/sig-20261104-006-evidence.json">synthetic inputs, expectations and actual outputs</a> accompany the candidate. The metric module is pinned to public commit <code>22483ab5df5eff562061953d564aac47a9423c2f</code>. The sole first-run assertion discrepancy was floating-point representation: expected 5.99 versus actual 5.989999999999999. Analysis preserved that run and changed only numerical comparison tolerance before passing. Production did not rerun or add experiments.</p><p>The <a href="https://raw.githubusercontent.com/ShengxuanQiu/MAServeBench/22483ab5df5eff562061953d564aac47a9423c2f/mas_workflow/app/semantic/metrics.py" target="_blank" rel="noreferrer">task-metric code</a> is the public primary implementation of the rules. Our execution is internal experimental evidence without an independent reproducer. Hardware findings remain author-reported from the <a href="https://arxiv.org/html/2610.40293v2" target="_blank" rel="noreferrer">v2 paper</a>. The pinned <a href="https://raw.githubusercontent.com/ShengxuanQiu/MAServeBench/22483ab5df5eff562061953d564aac47a9423c2f/docs/REPRODUCIBILITY.md" target="_blank" rel="noreferrer">reproducibility documentation</a> states that the cleaned public core excludes original machine-specific result archives; mock fixtures cannot substitute for paper hardware results.</p><p>Publication is not validation; citation is not endorsement; peer review is not proof. Self-reported evidence is not independent evidence, and successful module execution does not establish general performance validity.</p><h2 id="what-a-causal-optimization-claim-would-still-require" tabindex="-1">What a causal optimization claim would still require <a class="header-anchor" href="#what-a-causal-optimization-claim-would-still-require" aria-label="Permalink to &quot;What a causal optimization claim would still require&quot;">​</a></h2><p>We lack the original frozen corpus, private result archives and complete model/hardware serving stack. The probe measures no request throughput, real arrival process, KV cache, replay executor or hardware profile. Its three capacity cells are synthetic summaries. Current public commits and original paper experiment versions must remain separately identified.</p><p>A serving evaluation can first retain a common set of readings: complete-task raw wall-clock latency, attempted/successful/timely counts, a pre-locked deadline, a named observation window and run validity. Repeated native/replay comparisons on an obtainable frozen corpus and specified hardware would then need to examine whether bindings, arrival variation and model changes alter the result. That evidence is needed to answer whether an optimization delivers more tasks on time or improves a narrower statistic alone.</p>',29))])}const v=s(d,[["render",c]]);export{y as __pageData,v as default};
